import{_ as t,o as n,c as o,ag as r}from"./chunks/framework.8tqBsFWt.js";const h=JSON.parse('{"title":"Client Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/clients.md","filePath":"reference/tools/clients.md"}'),c={name:"reference/tools/clients.md"};function a(i,e,s,l,d,p){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="client-tools" tabindex="-1">Client Tools <a class="header-anchor" href="#client-tools" aria-label="Permalink to &quot;Client Tools&quot;">​</a></h1><hr><h2 id="list_clients" tabindex="-1">list_clients <a class="header-anchor" href="#list_clients" aria-label="Permalink to &quot;list_clients {#list_clients}&quot;">​</a></h2><p>All clients with aggregated project counts.</p><p><strong>Reads from</strong>: <code>04. Clients</code>, <code>02. Projects</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><hr><h2 id="create_client" tabindex="-1">create_client <a class="header-anchor" href="#create_client" aria-label="Permalink to &quot;create_client {#create_client}&quot;">​</a></h2><p>Create a new client organisation. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>04. Clients</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>client_name</code></p><blockquote><p>Clients are also auto-created when you create a project for a client that doesn&#39;t exist yet. The &quot;Internal&quot; client is auto-created when the first internal project is provisioned.</p></blockquote><hr><h2 id="rename_client" tabindex="-1">rename_client <a class="header-anchor" href="#rename_client" aria-label="Permalink to &quot;rename_client {#rename_client}&quot;">​</a></h2><p>Rename a client organisation. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>04. Clients</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>old_name</code>, <code>new_name</code></p><blockquote><p>Projects reference their client by ID, so no project rows need to be rewritten — the new name appears everywhere automatically on the next read.</p><p>The <code>Internal</code> client is protected and cannot be renamed. A rename attempt that collides with an existing client name is rejected.</p></blockquote><p><strong>Returns</strong>: <code>client_id</code>, <code>old_name</code>, <code>new_name</code>, <code>projects_affected</code></p><hr><h2 id="archive_client" tabindex="-1">archive_client <a class="header-anchor" href="#archive_client" aria-label="Permalink to &quot;archive_client {#archive_client}&quot;">​</a></h2><p>Archive a client so it no longer appears in menus or as a write target. <strong>Owner only.</strong> Historical references and project data are preserved. Use <code>unarchive_client</code> to restore.</p><p><strong>Writes to</strong>: <code>04. Clients</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>client_name</code></p><blockquote><p>Hard fails (409) if any active project references the client — cancel those projects first. The <code>Internal</code> client is protected and cannot be archived.</p></blockquote><p><strong>Returns</strong>: <code>client_id</code>, <code>client_name</code></p><hr><h2 id="unarchive_client" tabindex="-1">unarchive_client <a class="header-anchor" href="#unarchive_client" aria-label="Permalink to &quot;unarchive_client {#unarchive_client}&quot;">​</a></h2><p>Restore an archived client so it appears in menus again. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>04. Clients</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>client_name</code></p><p><strong>Returns</strong>: <code>client_id</code>, <code>client_name</code></p><hr><h2 id="delete_client" tabindex="-1">delete_client <a class="header-anchor" href="#delete_client" aria-label="Permalink to &quot;delete_client {#delete_client}&quot;">​</a></h2><p>Permanently hard-delete a client. <strong>Owner only.</strong> Only allowed when the client has zero projects of any status (active, cancelled, or completed). Use <code>archive_client</code> for clients that have history.</p><p><strong>Writes to</strong>: <code>04. Clients</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>client_name</code> or <code>client_id</code></p><blockquote><p>Blocked with 400 if the client has any projects (including cancelled ones — they still own history). The <code>Internal</code> client is permanently protected and returns 403. This action is irreversible — there is no undo.</p></blockquote><p><strong>Returns</strong>: <code>client_id</code>, <code>name</code>, <code>message</code></p><hr><h2 id="get_client_summary" tabindex="-1">get_client_summary <a class="header-anchor" href="#get_client_summary" aria-label="Permalink to &quot;get_client_summary {#get_client_summary}&quot;">​</a></h2><p>Aggregated view of a client&#39;s projects — hours, budget, and financials.</p><p><strong>Reads from</strong>: <code>04. Clients</code>, <code>02. Projects</code>, <code>01. Time Entries</code>, <code>22. Projects Master</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>client_name</code></p><p><strong>Returns</strong>: client name, active projects, total hours logged, total hours budget, % budget used, revenue (Owner only), cost (Owner only), margin (Owner only)</p><p>Financial rollups are client-aware: &quot;How&#39;s Nike doing?&quot; aggregates all Nike projects (Nike Campaign, Nike Rebrand, Nike Social, etc.) into a single summary.</p>',46)])])}const g=t(c,[["render",a]]);export{h as __pageData,g as default};
